    public void setIdleTimeSeconds(int idleTimeSeconds) {
        if (idleTimeSeconds > 0) {
            IdleStateHandler idleStateHandler = new IdleStateHandler(idleTimeSeconds, 0, 0);

            try {
                channel.pipeline().remove(ChannelHandlerConstant.KEEP_ALIVE_TIMER_HANDLER_NAME);
            } catch (NoSuchElementException e) {
                // Should happen
            }

            try {
                channel.pipeline().addBefore(ChannelHandlerConstant.MQTT_DECODER_HANDLER_NAME,
                        ChannelHandlerConstant.KEEP_ALIVE_TIMER_HANDLER_NAME, idleStateHandler);
                LOGGER.debug("Added IdleStateHandler (channel={}, idleTimeSeconds={})", this, idleTimeSeconds);
            } catch (NoSuchElementException e) {
                // Should not happen
                LOGGER.error("Could not add IdleStateHandler: {} (channel={})", e.getMessage(), channel);
            }
        }
    }
